<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Category; use App\Models\ContentItem; use App\Models\Setting; use App\Models\ExternalLink; use App\Services\ApiResponse;
class HomeController extends Controller { public function index(){ $settings=Setting::publicMap(); $featured=ContentItem::where('status','published')->whereIn('type',['tourist_place','news','event','job'])->latest('published_at')->limit(12)->with(['location','media','contacts'])->get(); return ApiResponse::ok(['banners'=>$settings['home_banners']??[],'sections'=>$settings['home_sections']??[],'menu'=>$settings['home_menu']??[],'featured'=>$featured,'settings'=>$settings],'Home content retrieved successfully'); } public function settings(){return ApiResponse::ok(Setting::publicMap(),'Settings retrieved successfully');} public function categories(){return ApiResponse::ok(Category::where('status','active')->orderBy('sort_order')->get(),'Categories retrieved successfully');} public function links(\Illuminate\Http\Request $request){ $q=ExternalLink::where('status','active'); if($request->filled('category')) $q->whereHas('category',fn($c)=>$c->where('slug',$request->string('category'))); return ApiResponse::ok($q->orderBy('sort_order')->get(),'External links retrieved successfully'); } public function page(string $slug){ $page=ContentItem::where('type','page')->where('slug',$slug)->where('status','published')->with('seo')->firstOrFail(); return ApiResponse::ok($page,'Page retrieved successfully'); }}
